import { MessageCircle, Phone, Mail } from 'lucide-react';
import {
  getWhatsAppLink,
  getViberLink,
  getPhoneLink,
  getEmailLink,
  getDisplayPhone
} from '../utils/contactLinks';

/**
 * Renders WhatsApp / Viber / Phone / Email CTAs.
 * `message` (optional) is used to prefill the WhatsApp text — e.g. a
 * product-specific inquiry generated by the ProductDetail page.
 */
export default function ContactButtons({
  message = '',
  size = 'default',
  show = ['whatsapp', 'viber', 'phone', 'email']
}) {
  const sizeClass = size === 'small' ? 'text-sm px-4 py-2' : '';

  return (
    <div className="flex flex-wrap gap-3">
      {show.includes('whatsapp') && (
        <a
          href={getWhatsAppLink(message)}
          target="_blank"
          rel="noopener noreferrer"
          className={`btn btn-whatsapp ${sizeClass}`}
          aria-label="Chat with us on WhatsApp"
        >
          <MessageCircle size={18} aria-hidden="true" />
          WhatsApp
        </a>
      )}
      {show.includes('viber') && (
        <a
          href={getViberLink()}
          className={`btn btn-viber ${sizeClass}`}
          aria-label={`Contact us on Viber, or call ${getDisplayPhone()} if Viber does not open`}
          title={`If Viber doesn't open, call us at ${getDisplayPhone()}`}
        >
          <MessageCircle size={18} aria-hidden="true" />
          Viber
        </a>
      )}
      {show.includes('phone') && (
        <a
          href={getPhoneLink()}
          className={`btn btn-outline ${sizeClass}`}
          aria-label={`Call us at ${getDisplayPhone()}`}
        >
          <Phone size={18} aria-hidden="true" />
          Call
        </a>
      )}
      {show.includes('email') && (
        <a
          href={getEmailLink()}
          className={`btn btn-outline ${sizeClass}`}
          aria-label="Email us"
        >
          <Mail size={18} aria-hidden="true" />
          Email
        </a>
      )}
    </div>
  );
}
